import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
grid = data[2:2 + r]
comp = {}
cid = 0
for i in range(r):
    for j in range(c):
        if grid[i][j] == '1' and (i, j) not in comp:
            comp[(i, j)] = cid
            st = [(i, j)]
            while st:
                x, y = st.pop()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] == '1' and (nx, ny) not in comp:
                        comp[(nx, ny)] = cid
                        st.append((nx, ny))
            cid += 1
A = [p for p in comp if comp[p] == 0]
B = [p for p in comp if comp[p] == 1]
print(min(abs(a[0] - b[0]) + abs(a[1] - b[1]) for a in A for b in B) - 1)

